'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  PRESS_LEAD_MS,
  pressedQuietOf,
  pressedSolidOf,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import {
  ArchiveIcon,
  BotIcon,
  PlayIcon,
  PlusIcon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { FIRST_SCENE, SCENES, type SceneCopy, type SceneId } from './data';
import { SceneArt } from './scenes';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

const CROSSFADE_TRANSITION: Transition = {
  duration: 0.22,
  ease: [0.23, 1, 0.32, 1],
};

const CROSSFADE_VARIANTS: Variants = {
  enter: { opacity: 0, scale: 0.98, filter: 'blur(4px)' },
  visible: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.98, filter: 'blur(4px)' },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

const ACTION_ICONS: Record<SceneId, React.ReactNode> = {
  runs: <PlayIcon />,
  inbox: <ArchiveIcon />,
  tools: <PlusIcon />,
  agents: <BotIcon />,
};

const LOOK_MS = 2400;

const BUSY_MS = 700;

const DONE_MS = 2000;

const REST_MS = 2800;

const RESET_AFTER_MS = 3200;

function crossfadeVariantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return CROSSFADE_VARIANTS;
}

function sceneOf(value: unknown) {
  return SCENES.find((candidate) => candidate.id === value);
}

function labelsOf(scene: SceneCopy): Record<MorphState, string> {
  return { idle: scene.idle, busy: scene.busy, done: scene.done };
}

export default function EmptyStates04() {
  const [sceneId, setSceneId] = useState<SceneId>(FIRST_SCENE);
  const [actionState, setActionState] = useState<MorphState>('idle');
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<string>();
  const { schedule, clearAll } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const isVisible = useDocumentVisible();
  const found = SCENES.find((candidate) => candidate.id === sceneId);
  const scene = found ?? SCENES[0];
  const variants = crossfadeVariantsOf(shouldReduceMotion);
  const pressedValues = [sceneId];

  function showScene(id: SceneId) {
    clearAll();
    setActionState('idle');
    setSceneId(id);
  }

  function runAction() {
    setActionState('busy');
    schedule(() => setActionState('done'), BUSY_MS);
    schedule(() => setActionState('idle'), DONE_MS);
  }

  function sequenceOf(index: number) {
    const sequence = [
      { after: LOOK_MS, run: () => press('action') },
      { after: PRESS_LEAD_MS, run: runAction },
    ];
    const next = SCENES[index + 1];
    if (next) {
      sequence.push(
        { after: REST_MS, run: () => press(`scene-${next.id}`) },
        { after: PRESS_LEAD_MS, run: () => showScene(next.id) }
      );
    }
    return sequence;
  }

  const steps = SCENES.flatMap((_, index) => sequenceOf(index));
  const { ref, isInView, isAutoplaying } = useAutoplay<HTMLDivElement>(steps, {
    loopAfter: RESET_AFTER_MS,
    onReset: () => showScene(FIRST_SCENE),
  });
  const isPlaying = isInView && isVisible;
  const spoken = spokenUnless(isAutoplaying, message);

  function pickScene(nextValues: unknown[]) {
    const [next] = nextValues;
    const picked = sceneOf(next);
    if (!picked) {
      return;
    }
    showScene(picked.id);
    setMessage(picked.title);
  }

  return (
    <div ref={ref} className='@container px-4 py-16 @2xl:px-6 @2xl:py-24'>
      <div className='mx-auto flex max-w-3xl flex-col items-center gap-8'>
        <div className='relative max-w-full overflow-x-auto'>
          <ToggleGroup
            aria-label='Empty states'
            value={pressedValues}
            onValueChange={pickScene}
            travel
            size='sm'
            indicatorClassName={THUMB}
            className='bg-foreground/[0.05] rounded-lg p-0.5'
          >
            {SCENES.map((item) => (
              <ToggleGroupItem
                key={item.id}
                value={item.id}
                className={cn(
                  'h-7 rounded-md px-2.5 text-xs',
                  pressedQuietOf(pressed === `scene-${item.id}`)
                )}
              >
                {item.tab}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </div>
        <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] w-full rounded-2xl p-2 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
          <div className='bg-foreground/[0.04] relative grid min-h-[26rem] place-items-center rounded-[calc(var(--radius-2xl)-0.5rem)] p-6 @2xl:p-10'>
            <AnimatePresence mode='popLayout' initial={false}>
              <motion.div
                key={scene.id}
                variants={variants}
                initial='enter'
                animate='visible'
                exit='exit'
                transition={CROSSFADE_TRANSITION}
                className='flex w-full flex-col items-center gap-6 text-center'
              >
                <SceneArt sceneId={scene.id} isPlaying={isPlaying} />
                <div className='flex max-w-sm flex-col gap-1.5'>
                  <h3 className='text-base font-semibold text-balance'>
                    {scene.title}
                  </h3>
                  <p className='text-muted-foreground text-[13px] text-pretty'>
                    {scene.description}
                  </p>
                </div>
                <MorphButton
                  type='button'
                  state={actionState}
                  labels={labelsOf(scene)}
                  idleIcon={ACTION_ICONS[scene.id]}
                  onClick={runAction}
                  className={cn(pressedSolidOf(pressed === 'action'))}
                />
              </motion.div>
            </AnimatePresence>
          </div>
        </div>
      </div>
      <LiveRegion message={spoken} />
    </div>
  );
}

'use client';

import { useRef } from 'react';

import {
  CheckIcon,
  InboxIcon,
  PlayIcon,
  PlusIcon,
} from '@/registry/ndeko/lib/icons';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';

import type { SceneId } from './data';
import { useSceneLoops, type SceneLoop } from './use-scene-loops';

/** An empty slot that invites an addition is the only dashed hairline of the system. */
const SLOT = 'hairline-border border-dashed border-foreground/20';

const RUN_BAR_WIDTHS = ['w-3/5', 'w-2/5', 'w-1/3'];

const AGENT_SLOTS = [0, 1, 2];

const TOOL_SLOTS = [0, 1, 2, 3];

const RISE_OFFSETS = ['start-[28%]', 'start-1/2', 'start-[72%]'];

function RunsArt() {
  return (
    <div className='flex h-full w-full flex-col justify-center gap-2.5'>
      {RUN_BAR_WIDTHS.map((width, index) => (
        <div
          key={width}
          data-loop='row'
          className={`${SLOT} flex h-10 items-center gap-3 rounded-lg px-3`}
        >
          <span className={`${SLOT} size-4 shrink-0 rounded-full`} />
          <span className={`bg-foreground/10 h-1.5 rounded-full ${width}`} />
          {index === 0 && (
            <span className='keycap-3d text-muted-foreground ms-auto flex size-6 shrink-0 items-center justify-center rounded-md'>
              <PlayIcon className='size-3' />
            </span>
          )}
        </div>
      ))}
    </div>
  );
}

function InboxArt() {
  return (
    <div className='relative flex h-full w-full items-center justify-center'>
      {RISE_OFFSETS.map((offset) => (
        <span
          key={offset}
          data-loop='rise'
          className={`chip-3d absolute bottom-[58%] -translate-x-1/2 opacity-0 [--chip:var(--success)] ${offset} flex size-[18px] items-center justify-center rounded-full`}
        >
          <CheckIcon className='size-3' />
        </span>
      ))}
      <span className='keycap-3d text-muted-foreground flex size-16 items-center justify-center rounded-2xl'>
        <InboxIcon className='size-7' />
      </span>
    </div>
  );
}

function ToolsArt() {
  return (
    <div className='flex h-full w-full items-center justify-center gap-3'>
      {TOOL_SLOTS.map((slot) => (
        <span
          key={slot}
          className={`${SLOT} text-muted-foreground relative flex size-14 items-center justify-center rounded-xl`}
        >
          <span
            data-loop='slot'
            aria-hidden='true'
            className='bg-primary/10 absolute inset-0 rounded-xl opacity-0'
          />
          <PlusIcon className='size-4 opacity-60' />
        </span>
      ))}
    </div>
  );
}

function AgentsArt() {
  return (
    <div className='flex h-full w-full items-center justify-center gap-3'>
      {AGENT_SLOTS.map((slot) => {
        if (slot === 0) {
          return (
            <span key={slot} data-loop='ghost' className='opacity-30'>
              <MeshTile seed='Planner' className='size-14 rounded-xl' />
            </span>
          );
        }
        return (
          <span
            key={slot}
            className={`${SLOT} text-muted-foreground flex size-14 items-center justify-center rounded-xl`}
          >
            <PlusIcon className='size-4 opacity-60' />
          </span>
        );
      })}
    </div>
  );
}

const ART: Record<SceneId, () => React.JSX.Element> = {
  runs: RunsArt,
  inbox: InboxArt,
  tools: ToolsArt,
  agents: AgentsArt,
};

const BREATH: Keyframe[] = [
  { opacity: 0.45 },
  { opacity: 1 },
  { opacity: 0.45 },
];

const RISE: Keyframe[] = [
  { opacity: 0, transform: 'translateY(10px) scale(0.9)' },
  { opacity: 1, transform: 'translateY(0) scale(1)', offset: 0.3 },
  { opacity: 0, transform: 'translateY(-26px) scale(1)' },
];

const LIGHT: Keyframe[] = [
  { opacity: 0 },
  { opacity: 1, offset: 0.25 },
  { opacity: 0, offset: 0.5 },
  { opacity: 0 },
];

const GHOST: Keyframe[] = [
  { opacity: 0.3, transform: 'scale(0.97)' },
  { opacity: 0.75, transform: 'scale(1)' },
  { opacity: 0.3, transform: 'scale(0.97)' },
];

const LOOPS: Record<SceneId, SceneLoop[]> = {
  runs: [
    {
      selector: '[data-loop="row"]',
      keyframes: BREATH,
      duration: 3600,
      stagger: 600,
    },
  ],
  inbox: [
    {
      selector: '[data-loop="rise"]',
      keyframes: RISE,
      duration: 3200,
      stagger: 1000,
    },
  ],
  tools: [
    {
      selector: '[data-loop="slot"]',
      keyframes: LIGHT,
      duration: 3200,
      stagger: 800,
    },
  ],
  agents: [
    { selector: '[data-loop="ghost"]', keyframes: GHOST, duration: 3600 },
  ],
};

type SceneArtProps = {
  sceneId: SceneId;
  isPlaying: boolean;
};

export function SceneArt({ sceneId, isPlaying }: SceneArtProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const Art = ART[sceneId];
  useSceneLoops(rootRef, LOOPS[sceneId], isPlaying);

  return (
    <div ref={rootRef} aria-hidden='true' className='h-40 w-full max-w-xs'>
      <Art />
    </div>
  );
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

export type SceneLoop = {
  selector: string;
  keyframes: Keyframe[];
  duration: number;
  /** Each part after the first starts this much later, so the loop travels across them. */
  stagger?: number;
};

/**
 * Calm loops on opacity and transform only, as Web Animations made once and paused whenever the
 * scene is not on screen. Under reduced motion none is made, so the scene stays as drawn.
 */
export function useSceneLoops(
  rootRef: RefObject<HTMLElement | null>,
  loops: readonly SceneLoop[],
  isPlaying: boolean
) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const animations = useRef<Animation[]>([]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root || shouldReduceMotion) {
      return;
    }
    const created: Animation[] = [];
    for (const loop of loops) {
      const parts = root.querySelectorAll<HTMLElement>(loop.selector);
      const stagger = loop.stagger ?? 0;
      parts.forEach((part, index) => {
        const animation = part.animate(loop.keyframes, {
          duration: loop.duration,
          delay: index * stagger,
          iterations: Infinity,
          easing: 'ease-in-out',
        });
        animation.pause();
        created.push(animation);
      });
    }
    animations.current = created;
    return () => {
      created.forEach((animation) => animation.cancel());
      animations.current = [];
    };
  }, [rootRef, loops, shouldReduceMotion]);

  useEffect(() => {
    for (const animation of animations.current) {
      if (isPlaying) {
        animation.play();
      } else {
        animation.pause();
      }
    }
  }, [isPlaying, loops, shouldReduceMotion]);
}

export type SceneId = 'runs' | 'inbox' | 'tools' | 'agents';

export type SceneCopy = {
  id: SceneId;
  tab: string;
  title: string;
  description: string;
  idle: string;
  busy: string;
  done: string;
};

